package com.hs.jxc.md.service;

import com.hs.jxc.md.api.ProductImageApi;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.audit.AuditWriter;
import com.hs.jxc.common.db.DbRows;
import com.hs.jxc.common.idempotency.IdempotencyExecutor;
import com.hs.jxc.attachment.*;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.service.AuthorizationService;
import java.nio.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** 唯一照片关系和向量备份；索引是可重建的不可变派生资产。 */
@Service
public class ProductImageService implements ProductImageApi {
    private final JdbcTemplate jdbc;private final AuthorizationService auth;private final AttachmentAssetService assets;private final JsonCodec json;private final AuditWriter audit;private final TransactionTemplate tx;
    public ProductImageService(JdbcTemplate jdbc,AuthorizationService auth,AttachmentAssetService assets,JsonCodec json,AuditWriter audit,PlatformTransactionManager tm){this.jdbc=jdbc;this.auth=auth;this.assets=assets;this.json=json;this.audit=audit;tx=new TransactionTemplate(tm);}
    private Access access(RequestContext ctx,boolean write){var a=auth.authorize(ctx);a.requireCountry();a.require(write?"md:product:edit":"md:product:view");return a;}
    private static long id(Map<String,Object> row,String field){return Inputs.id(row.get(field));}
    @SuppressWarnings("unchecked") private Map<String,Object> map(Object value){return value instanceof Map<?,?>?(Map<String,Object>)value:json.readMap(value.toString());}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Object value){if(!(value instanceof List<?> list))throw Inputs.bad("图库清单不完整");return list.stream().map(this::map).toList();}
    private void galleryLock(Access a){jdbc.queryForObject("SELECT pg_advisory_xact_lock(?)",Object.class,a.requireCountry()+3000000000000000L);}
    private Map<String,Object> metadata(Map<String,Object> input){var out=new LinkedHashMap<String,Object>();for(String key:List.of("countryId","modelName","modelVersion","preprocessVersion","dimension","featureIds","coverage","basisHash"))out.put(key,input.get(key));return out;}
    private String canonical(Object value){return json.write(IdempotencyExecutor.canonical(value));}
    private Map<String,Object> asset(Access a,long id){var found=jdbc.queryForList("SELECT * FROM sys_attachment WHERE country_id=? AND id=? AND status='VALID' AND object_status='AVAILABLE'",a.requireCountry(),id);if(found.size()!=1)throw ApiException.notFound();return found.getFirst();}
    private void product(long id){if(jdbc.queryForObject("SELECT count(*) FROM md_product WHERE id=? AND status='ENABLED'",Integer.class,id)!=1)throw ApiException.notFound();}
    private Map<String,Object> featureRow(Access a,long id){var found=jdbc.queryForList("SELECT f.* FROM image_feature f WHERE f.country_id=? AND f.id=? AND f.model_name=? AND f.model_version=? AND f.preprocess_version=? AND EXISTS(SELECT 1 FROM md_product_image i JOIN md_product p ON p.id=i.product_id AND p.status='ENABLED' WHERE i.country_id=f.country_id AND i.attachment_id=f.attachment_id AND i.status='ACTIVE')",a.requireCountry(),id,MODEL,MODEL_VERSION,PREPROCESS);if(found.size()!=1)throw ApiException.notFound();return found.getFirst();}
    public Map<String,Object> link(RequestContext ctx,long product,long attachment){return tx.execute(s->{var a=access(ctx,true);galleryLock(a);product(product);var file=asset(a,attachment);if(!Set.of("image/png","image/jpeg","image/webp","image/gif").contains(file.get("content_type"))||((Number)file.get("size")).longValue()>AttachmentAssetService.Policy.PURCHASE_IMAGE.maxBytes)throw Inputs.bad("只能关联合格的商品原图");
        long image=jdbc.queryForObject("INSERT INTO md_product_image(country_id,product_id,attachment_id,created_by) VALUES(?,?,?,?) ON CONFLICT(country_id,product_id,attachment_id) WHERE status='ACTIVE' DO UPDATE SET product_id=excluded.product_id RETURNING id",Long.class,a.requireCountry(),product,attachment,a.userId());
        jdbc.update("INSERT INTO image_feature(country_id,attachment_id,model_name,model_version,preprocess_version,created_by) VALUES(?,?,?,?,?,?) ON CONFLICT(country_id,attachment_id,model_name,model_version,preprocess_version) DO NOTHING",a.requireCountry(),attachment,MODEL,MODEL_VERSION,PREPROCESS,a.userId());long feature=jdbc.queryForObject("SELECT id FROM image_feature WHERE country_id=? AND attachment_id=? AND model_name=? AND model_version=? AND preprocess_version=?",Long.class,a.requireCountry(),attachment,MODEL,MODEL_VERSION,PREPROCESS);audit.append(ctx,"PRODUCT_IMAGE_LINK","PRODUCT_IMAGE",image,null,Map.of("productId",product,"attachmentId",attachment));return Map.of("imageId",image,"featureId",feature,"attachmentId",attachment,"sha256",file.get("sha256"));
    });}
    public List<Map<String,Object>> list(RequestContext ctx,long product){return tx.execute(s->{var a=access(ctx,false);product(product);return jdbc.queryForList("SELECT i.id,i.product_id,i.is_primary,i.sort_order,i.version,f.id feature_id,f.feature_status,f.index_status,f.error_message FROM md_product_image i LEFT JOIN image_feature f ON f.country_id=i.country_id AND f.attachment_id=i.attachment_id AND f.model_name=? AND f.model_version=? AND f.preprocess_version=? WHERE i.country_id=? AND i.product_id=? AND i.status='ACTIVE' ORDER BY i.sort_order,i.id",MODEL,MODEL_VERSION,PREPROCESS,a.requireCountry(),product).stream().map(DbRows::camel).toList();});}
    public AttachmentService.Download content(RequestContext ctx,long image){var file=tx.execute(s->{var a=access(ctx,false);var found=jdbc.queryForList("SELECT attachment_id,product_id FROM md_product_image WHERE country_id=? AND id=? AND status='ACTIVE'",a.requireCountry(),image);if(found.size()!=1)throw ApiException.notFound();product(id(found.getFirst(),"product_id"));return asset(a,id(found.getFirst(),"attachment_id"));});byte[] bytes=assets.read(file,AttachmentAssetService.Policy.PURCHASE_IMAGE);tx.execute(s->{var a=access(ctx,false);if(jdbc.queryForObject("SELECT count(*) FROM md_product_image WHERE country_id=? AND id=? AND status='ACTIVE'",Integer.class,a.requireCountry(),image)!=1)throw ApiException.notFound();return null;});return new AttachmentService.Download(file.get("file_name").toString(),file.get("content_type").toString(),bytes);}
    public List<Map<String,Object>> pendingFeatures(RequestContext ctx){return tx.execute(s->{var a=access(ctx,true);a.require("md:product:view");galleryLock(a);jdbc.update("INSERT INTO image_feature(country_id,attachment_id,model_name,model_version,preprocess_version,created_by) SELECT DISTINCT i.country_id,i.attachment_id,?,?,?,? FROM md_product_image i JOIN md_product p ON p.id=i.product_id AND p.status='ENABLED' JOIN sys_attachment a ON a.country_id=i.country_id AND a.id=i.attachment_id AND a.status='VALID' AND a.object_status='AVAILABLE' WHERE i.country_id=? AND i.status='ACTIVE' ON CONFLICT(country_id,attachment_id,model_name,model_version,preprocess_version) DO NOTHING",MODEL,MODEL_VERSION,PREPROCESS,a.userId(),a.requireCountry());return jdbc.queryForList("SELECT f.id feature_id,f.attachment_id,a.sha256 FROM image_feature f JOIN sys_attachment a ON a.country_id=f.country_id AND a.id=f.attachment_id AND a.status='VALID' AND a.object_status='AVAILABLE' WHERE f.country_id=? AND f.model_name=? AND f.model_version=? AND f.preprocess_version=? AND f.feature_status<>'READY' AND EXISTS(SELECT 1 FROM md_product_image i JOIN md_product p ON p.id=i.product_id AND p.status='ENABLED' WHERE i.country_id=f.country_id AND i.attachment_id=f.attachment_id AND i.status='ACTIVE') ORDER BY f.id",a.requireCountry(),MODEL,MODEL_VERSION,PREPROCESS).stream().map(DbRows::camel).toList();});}
    public Map<String,Object> feature(RequestContext ctx,long feature){return tx.execute(s->{var a=access(ctx,false);var f=featureRow(a,feature);var file=asset(a,id(f,"attachment_id"));var out=DbRows.camel(f);out.remove("featureData");out.put("sha256",file.get("sha256"));if(f.get("feature_data") instanceof byte[] data)out.put("data",Base64.getEncoder().encodeToString(data));return out;});}
    public AttachmentService.Download featureContent(RequestContext ctx,long feature){var file=tx.execute(s->{var a=access(ctx,false);return asset(a,id(featureRow(a,feature),"attachment_id"));});var data=assets.read(file,AttachmentAssetService.Policy.PURCHASE_IMAGE);feature(ctx,feature);return new AttachmentService.Download(file.get("file_name").toString(),file.get("content_type").toString(),data);}
    private void validateModel(Map<String,Object> result){if(!MODEL.equals(result.get("modelName"))||!MODEL_VERSION.equals(result.get("modelVersion"))||!PREPROCESS.equals(result.get("preprocessVersion")))throw new ApiException(409,"GALLERY_MODEL_CHANGED","模型或预处理版本不一致");}
    public void saveFeature(RequestContext ctx,long feature,Map<String,Object> result){validateModel(result);int dimension=Math.toIntExact(Inputs.id(result.get("dimension")));if(dimension!=384)throw Inputs.bad("DINOv2特征维度须为384");byte[] data;try{data=Base64.getDecoder().decode(Inputs.required(result,"data"));}catch(IllegalArgumentException invalid){throw Inputs.bad("特征编码无效");}if(data.length!=dimension*4)throw Inputs.bad("特征维度与字节数不一致");var buffer=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);double norm=0;while(buffer.hasRemaining()){float value=buffer.getFloat();if(!Float.isFinite(value))throw Inputs.bad("特征含非有限值");norm+=(double)value*value;}if(!Double.isFinite(norm)||Math.abs(norm-1)>0.0001)throw Inputs.bad("特征不是有效归一化向量");
        tx.execute(s->{var a=access(ctx,true);galleryLock(a);jdbc.queryForList("SELECT id FROM image_feature WHERE country_id=? AND id=? FOR UPDATE",a.requireCountry(),feature);var f=featureRow(a,feature);if("READY".equals(f.get("feature_status"))){if(!Arrays.equals((byte[])f.get("feature_data"),data))throw new ApiException(409,"GALLERY_FEATURE_CHANGED","同一模型特征已存在不同内容");return null;}jdbc.update("UPDATE image_feature SET dimension=?,feature_data=?,feature_status='READY',index_status='PENDING',error_message=NULL,version=version+1 WHERE country_id=? AND id=?",dimension,data,a.requireCountry(),feature);return null;});}
    public void failFeature(RequestContext ctx,long feature,String message){tx.execute(s->{var a=access(ctx,true);featureRow(a,feature);jdbc.update("UPDATE image_feature SET feature_status='FAILED',feature_data=NULL,index_status='PENDING',error_message=?,version=version+1 WHERE country_id=? AND id=? AND feature_status<>'READY'",message,a.requireCountry(),feature);return null;});}
    private String eligible(){return " FROM md_product_image i JOIN md_product p ON p.id=i.product_id AND p.status='ENABLED' JOIN md_country_sku sku ON sku.country_id=i.country_id AND sku.product_id=p.id AND sku.status='ENABLED' JOIN sys_attachment a ON a.country_id=i.country_id AND a.id=i.attachment_id AND a.status='VALID' AND a.object_status='AVAILABLE' WHERE i.country_id=? AND i.status='ACTIVE'";}
    public Map<String,Object> galleryInput(RequestContext ctx){return gallerySnapshot(ctx,true);}
    private Map<String,Object> gallerySnapshot(RequestContext ctx,boolean includeVectors){return tx.execute(s->{var a=access(ctx,false);var photos=jdbc.queryForList("SELECT i.id,i.version,i.product_id,i.attachment_id,p.version product_version,sku.version sku_version,sku.status sku_status,a.status asset_status,a.object_status FROM md_product_image i JOIN md_product p ON p.id=i.product_id AND p.status='ENABLED' JOIN sys_attachment a ON a.country_id=i.country_id AND a.id=i.attachment_id LEFT JOIN md_country_sku sku ON sku.country_id=i.country_id AND sku.product_id=p.id WHERE i.country_id=? AND i.status='ACTIVE' ORDER BY i.id",a.requireCountry());var features=jdbc.queryForList("SELECT DISTINCT f.id,f.attachment_id,f.dimension,encode(sha256(f.feature_data),'hex') vector_sha"+(includeVectors?",f.feature_data":"")+" FROM image_feature f JOIN md_product_image i ON i.country_id=f.country_id AND i.attachment_id=f.attachment_id AND i.status='ACTIVE' JOIN md_product p ON p.id=i.product_id AND p.status='ENABLED' JOIN md_country_sku sku ON sku.country_id=i.country_id AND sku.product_id=p.id AND sku.status='ENABLED' JOIN sys_attachment a ON a.country_id=i.country_id AND a.id=i.attachment_id AND a.status='VALID' AND a.object_status='AVAILABLE' WHERE f.country_id=? AND f.model_name=? AND f.model_version=? AND f.preprocess_version=? AND f.feature_status='READY' ORDER BY f.id",a.requireCountry(),MODEL,MODEL_VERSION,PREPROCESS);var descriptors=features.stream().map(f->Map.<String,Object>of("featureId",f.get("id"),"dimension",f.get("dimension"),"sha256",f.get("vector_sha"))).toList();var coveredAssets=features.stream().map(f->f.get("attachment_id")).collect(java.util.stream.Collectors.toSet());var eligiblePhotos=photos.stream().filter(photo->"ENABLED".equals(photo.get("sku_status"))&&"VALID".equals(photo.get("asset_status"))&&"AVAILABLE".equals(photo.get("object_status"))).toList();long covered=eligiblePhotos.stream().filter(photo->coveredAssets.contains(photo.get("attachment_id"))).count();var out=new LinkedHashMap<String,Object>();out.put("countryId",a.requireCountry());out.put("modelName",MODEL);out.put("modelVersion",MODEL_VERSION);out.put("preprocessVersion",PREPROCESS);out.put("dimension",384);out.put("featureIds",features.stream().map(f->f.get("id")).toList());if(includeVectors)out.put("features",features.stream().map(f->Map.<String,Object>of("featureId",f.get("id"),"dimension",f.get("dimension"),"data",Base64.getEncoder().encodeToString((byte[])f.get("feature_data")))).toList());out.put("coverage",Map.of("photos",photos.size(),"eligiblePhotos",eligiblePhotos.size(),"readyPhotos",covered,"features",features.size()));out.put("basisHash",Digests.sha256(canonical(Map.of("photos",photos,"features",descriptors,"model",MODEL+MODEL_VERSION+PREPROCESS,"country",a.requireCountry()))));return out;});}
    public Map<String,Object> gallery(RequestContext ctx){return tx.execute(s->{var a=access(ctx,false);var input=gallerySnapshot(ctx,false);var current=jdbc.queryForList("SELECT * FROM md_image_index_generation WHERE country_id=? AND model_name=? AND model_version=? AND preprocess_version=? ORDER BY created_at DESC,id DESC LIMIT 1",a.requireCountry(),MODEL,MODEL_VERSION,PREPROCESS);var active=jdbc.queryForList("SELECT * FROM md_image_index_generation WHERE country_id=? AND model_name=? AND model_version=? AND preprocess_version=? AND active LIMIT 1",a.requireCountry(),MODEL,MODEL_VERSION,PREPROCESS).stream().findFirst();long count=((Number)map(input.get("coverage")).get("photos")).longValue();var out=new LinkedHashMap<String,Object>();out.put("status",count==0?"EMPTY":active.isPresent()?Objects.equals(active.get().get("basis_hash"),input.get("basisHash"))&&((Number)map(input.get("coverage")).get("readyPhotos")).longValue()==count?"READY":"PARTIAL":!current.isEmpty()&&"FAILED".equals(current.getFirst().get("status"))?"FAILED":"NOT_READY");out.put("coverage",input.get("coverage"));out.put("manifest",active.isEmpty()?null:map(active.get().get("manifest")));out.put("lastError",current.isEmpty()?null:current.getFirst().get("error_message"));return out;});}
    private Map<String,Object> generation(Access a,String generation){var found=jdbc.queryForList("SELECT * FROM md_image_index_generation WHERE country_id=? AND generation=?",a.requireCountry(),generation);if(found.size()!=1)throw ApiException.notFound();return found.getFirst();}
    public void beginGeneration(RequestContext ctx,String generation,Map<String,Object> input){if(!generation.matches("[a-f0-9]{32}"))throw Inputs.bad("索引代次无效");validateModel(input);tx.execute(s->{var a=access(ctx,true);if(!Objects.equals(input.get("basisHash"),gallerySnapshot(ctx,false).get("basisHash")))throw new ApiException(409,"INPUT_CHANGED","图库资料已变化，请重新生成");jdbc.update("INSERT INTO md_image_index_generation(country_id,generation,model_name,model_version,preprocess_version,basis_hash,manifest,created_by) VALUES(?,?,?,?,?,?,?::jsonb,?) ON CONFLICT(country_id,generation) DO NOTHING",a.requireCountry(),generation,MODEL,MODEL_VERSION,PREPROCESS,input.get("basisHash"),json.write(metadata(input)),a.userId());if(!Objects.equals(generation(a,generation).get("basis_hash"),input.get("basisHash")))throw new ApiException(409,"INPUT_CHANGED","同一索引代次不能改变内容");return null;});}
    public Map<String,Object> generationStatus(RequestContext ctx,String generation){return tx.execute(s->{var a=access(ctx,false);var found=jdbc.queryForList("SELECT status,manifest FROM md_image_index_generation WHERE country_id=? AND generation=?",a.requireCountry(),generation);return found.isEmpty()?Map.of("status","NOT_FOUND"):Map.of("status",found.getFirst().get("status"),"manifest",map(found.getFirst().get("manifest")));});}
    public void failGeneration(RequestContext ctx,String generation,String message){tx.execute(s->{var a=access(ctx,true);galleryLock(a);var found=jdbc.queryForList("SELECT * FROM md_image_index_generation WHERE country_id=? AND generation=? FOR UPDATE",a.requireCountry(),generation);if(found.isEmpty())return null;var row=found.getFirst();if(!"READY".equals(row.get("status"))){jdbc.update("UPDATE md_image_index_generation SET status='FAILED',error_message=? WHERE country_id=? AND generation=?",message,a.requireCountry(),generation);for(Object feature:(List<?>)map(row.get("manifest")).get("featureIds"))jdbc.update("UPDATE image_feature SET index_status='FAILED',error_message=?,version=version+1 WHERE country_id=? AND id=? AND feature_status='READY' AND index_status<>'READY'",message,a.requireCountry(),feature);}return null;});}

    public Map<String,Object> publishIndex(RequestContext ctx,String generation,Map<String,Object> input,Map<String,Object> result,Runnable commitGuard){validateModel(result);if(!Objects.equals(generation,result.get("generation"))||!canonical(input.get("featureIds")).equals(canonical(result.get("featureIds")))||!Objects.equals(result.get("dimension"),384)||!canonical(result.get("countryId")).equals(canonical(input.get("countryId"))))throw Inputs.bad("索引清单与请求国家、特征或维度不一致");byte[] bytes;try{bytes=Base64.getDecoder().decode(Inputs.required(result,"indexBase64"));}catch(IllegalArgumentException invalid){throw Inputs.bad("索引编码无效");}if(!Objects.equals(AttachmentObjectStore.sha256(bytes),result.get("indexSha256")))throw Inputs.bad("索引哈希不一致");tx.execute(s->{access(ctx,true);return null;});var prepared=assets.prepare(ctx,AttachmentAssetService.Policy.PRODUCT_INDEX,generation+".faiss","application/octet-stream",bytes);
        return tx.execute(s->{var a=access(ctx,true);commitGuard.run();galleryLock(a);jdbc.queryForList("SELECT i.id"+eligible()+" FOR SHARE OF i,p,sku,a",a.requireCountry());jdbc.queryForList("SELECT id FROM image_feature WHERE country_id=? AND model_name=? AND model_version=? AND preprocess_version=? FOR SHARE",a.requireCountry(),MODEL,MODEL_VERSION,PREPROCESS);var row=generation(a,generation);if("READY".equals(row.get("status"))){var existing=map(row.get("manifest"));if(!Objects.equals(existing.get("indexSha256"),prepared.sha256())||!Objects.equals(row.get("basis_hash"),input.get("basisHash")))throw new ApiException(409,"GALLERY_GENERATION_CONFLICT","已发布索引代次不能改变内容");return existing;}if(!Objects.equals(input.get("basisHash"),gallerySnapshot(ctx,false).get("basisHash")))throw new ApiException(409,"INPUT_CHANGED","生成期间图库关系已变化，未发布旧索引");long attachment=assets.register(ctx,prepared);var manifest=metadata(input);manifest.put("format","GalleryManifestV1");manifest.put("generation",generation);manifest.put("indexSha256",prepared.sha256());manifest.put("manifestSha256",Digests.sha256(canonical(manifest)));jdbc.update("UPDATE md_image_index_generation SET active=false WHERE country_id=? AND model_name=? AND model_version=? AND preprocess_version=? AND active",a.requireCountry(),MODEL,MODEL_VERSION,PREPROCESS);jdbc.update("UPDATE md_image_index_generation SET status='READY',active=true,manifest=?::jsonb,attachment_id=?,error_message=NULL WHERE country_id=? AND generation=?",json.write(manifest),attachment,a.requireCountry(),generation);for(Object feature:(List<?>)input.get("featureIds"))jdbc.update("UPDATE image_feature SET index_status='READY',error_message=NULL,version=version+1 WHERE country_id=? AND id=? AND feature_status='READY'",a.requireCountry(),feature);audit.append(ctx,"PRODUCT_GALLERY_PUBLISH","PRODUCT_GALLERY",id(row,"id"),null,manifest);return manifest;});}
    public AttachmentService.Download indexContent(RequestContext ctx,String generation){var file=tx.execute(s->{var a=access(ctx,false);var row=generation(a,generation);if(!"READY".equals(row.get("status")))throw new ApiException(503,"GALLERY_NOT_READY","索引尚未发布");return asset(a,id(row,"attachment_id"));});var data=assets.read(file,AttachmentAssetService.Policy.PRODUCT_INDEX);tx.execute(s->{access(ctx,false);return null;});return new AttachmentService.Download(generation+".faiss","application/octet-stream",data);}
    public List<Map<String,Object>> resolveHits(RequestContext ctx,String generation,List<Map<String,Object>> hits){return tx.execute(s->{var a=access(ctx,false);var row=generation(a,generation);if(!"READY".equals(row.get("status")))throw new ApiException(503,"GALLERY_NOT_READY","索引尚未发布");var ids=(List<?>)map(row.get("manifest")).get("featureIds");var out=new ArrayList<Map<String,Object>>();for(var hit:hits){long feature=id(hit,"featureId");double score;try{score=Double.parseDouble(hit.get("score").toString());}catch(RuntimeException invalid){throw Inputs.bad("检索分数无效");}if(!Double.isFinite(score)||score< -1||score>1||ids.stream().noneMatch(v->Inputs.id(v)==feature))throw Inputs.bad("检索返回了清单之外的特征或分数");for(var photo:jdbc.queryForList("SELECT i.id image_id,f.id feature_id,p.id product_id,p.product_code,p.name,p.spec,p.base_unit FROM image_feature f JOIN md_product_image i ON i.country_id=f.country_id AND i.attachment_id=f.attachment_id AND i.status='ACTIVE' JOIN md_product p ON p.id=i.product_id AND p.status='ENABLED' JOIN md_country_sku sku ON sku.country_id=i.country_id AND sku.product_id=p.id AND sku.status='ENABLED' JOIN sys_attachment a ON a.country_id=i.country_id AND a.id=i.attachment_id AND a.status='VALID' AND a.object_status='AVAILABLE' WHERE f.country_id=? AND f.id=? AND f.feature_status='READY'",a.requireCountry(),feature)){var dto=DbRows.camel(photo);dto.put("visualScore",score);out.add(dto);}}return out;});}
}
